// ============================================================
// CONFIGURAÇÃO DA UNIDADE - Oral Foz
// Normaliza entrada e centraliza config da clínica
// ============================================================
const body = $input.item.json.body || $input.item.json;
const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';
const TIMEZONE = 'America/Sao_Paulo';

// --- CONFIG FIXA DA CLÍNICA ---
const CONFIG = {
  nome_unidade:     'Oral Foz',
  nome_empresa:     'Oral Foz',
  timezone:         TIMEZONE,
  duracao_servico:  60,
  dias_atendimento: [1, 2, 3, 4, 5, 6], // Segunda a Sábado (agenda combinada Klayton + Eyla)
  profissionais: {
    klayton: { idpro: '2',  nome: 'KLAYTON JOSÉ FIRMIANO' },
    eyla:    { idpro: '62', nome: 'EYLA RODRIGUES DE AGUIAR' }
  },
  janelas_por_dia: {
    1: { profissional: 'klayton', janelas: [{ inicio: '13:00', fim: '18:00' }] }, // Segunda - Klayton tarde
    2: { profissional: 'eyla',    janelas: [{ inicio: '09:00', fim: '18:00' }] }, // Terça - Eyla dia todo
    3: { profissional: 'klayton', janelas: [{ inicio: '13:00', fim: '18:00' }] }, // Quarta - Klayton tarde
    4: { profissional: 'eyla',    janelas: [{ inicio: '09:00', fim: '18:00' }] }, // Quinta - Eyla dia todo
    5: { profissional: 'klayton', janelas: [{ inicio: '09:00', fim: '12:00' }] }, // Sexta - Klayton manhã
    6: { profissional: 'eyla',    janelas: [{ inicio: '08:00', fim: '12:00' }] }  // Sábado - Eyla manhã
  },
  authorization: 'rFTCF93DuLzJ2gm2ATSIXx4LIW3ExRA6XW0TNF5suN5BE10FJGqRxo1FiRoN'
};

// --- NORMALIZAÇÃO DE TELEFONE ---
const telefoneRaw    = (body.telefone_cliente || body.telefone_contato || body.telefone || '').toString();
const telefoneLimpo  = telefoneRaw.replace(/\D/g, '');
const telefoneSemDDI = telefoneLimpo.length > 11 ? telefoneLimpo.slice(-11) : telefoneLimpo;

// --- NORMALIZAÇÃO DE NOME ---
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';

// --- NORMALIZAÇÃO DE DATA/HORA ---
const hoje      = DateTime.now().setZone(TIMEZONE);
const acaoAtual = body.action || body.acao_fluxo || '';

// data_inicio como data de agendamento apenas em ações que precisam de data específica
// Em verificar_disponibilidade, data_inicio é só âncora de busca — não deve virar data_agendada
const acoesComData = ['realizar_agendamento', 'cancelar_agendamento', 'remarcar_agendamento', 'consultar_agendamento'];
const dataRaw = body.data_iso || body.data_agendada ||
  (acoesComData.includes(acaoAtual) ? body.data_inicio : '') || '';

let dtParsed = null;
if (dataRaw) {
  const formatos = [
    () => DateTime.fromISO(dataRaw,                         { zone: TIMEZONE }),
    () => DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE }),
    () => DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE }),
    () => DateTime.fromFormat(dataRaw, 'yyyy-MM-dd',       { zone: TIMEZONE }),
  ];
  for (const fn of formatos) {
    const dt = fn();
    if (dt.isValid) { dtParsed = dt; break; }
  }
}

const horaDoISO = (dtParsed && (dtParsed.hour > 0 || dtParsed.minute > 0)) ? dtParsed.toFormat('HH:mm') : '';

// Filtra string "null" e valores inválidos no horário
const horarioRaw   = body.horario_agendado || body.horario || '';
const horarioFinal = (horarioRaw && horarioRaw !== 'null' && horarioRaw.length >= 4)
  ? horarioRaw
  : horaDoISO;

const dataFinal = dtParsed?.isValid ? dtParsed.toFormat('yyyy-MM-dd') : '';

// --- VALIDAÇÃO DE DIA DA SEMANA ---
const NOMES_DIA = { 1:'Segunda-feira',2:'Terça-feira',3:'Quarta-feira',4:'Quinta-feira',5:'Sexta-feira',6:'Sábado',7:'Domingo' };
let diaSemanaValido = null;
let diaSemanaAberto = null;
if (dtParsed?.isValid) {
  diaSemanaValido = CONFIG.dias_atendimento.includes(dtParsed.weekday);
  diaSemanaAberto = NOMES_DIA[dtParsed.weekday];
}

return {
  json: {
    acao_fluxo:       acaoAtual,
    nome_paciente:    nomePaciente,
    telefone_limpo:   telefoneLimpo,
    telefone_limpo: telefoneSemDDI,
    // Normaliza data_nascimento para yyyy-MM-dd independente do formato recebido
    data_nascimento: (() => {
      const dnRaw = body.data_nascimento || '';
      if (!dnRaw) return '';
      if (/^\d{2}\/\d{2}\/\d{4}$/.test(dnRaw)) {
        const [d, m, a] = dnRaw.split('/');
        return `${a}-${m}-${d}`;
      }
      return dnRaw;
    })(),
    data_inicio:       hoje.toFormat('yyyy-MM-dd'),
    data_agendada:     dataFinal,
    data_antiga:       body.data_antiga || body['data-antiga'] || '',
    horario_agendado:  horarioFinal,
    dia_semana_valido: diaSemanaValido,
    dia_semana_nome:   diaSemanaAberto,
    config_agenda:     CONFIG,
    id_atendimento:    idAtendimento,
    helena_company_id: 'b2489455-9691-43bd-a130-6e84296dad9c'
  }
};

// ============================================================
// VERIFICAR DISPONIBILIDADE
// Busca datas e horários livres na API eClinica (Klayton + Eyla)
// ============================================================
const cfg       = $json.config_agenda;
const BASE_URL  = 'https://eclinica.app/api/v2';
const DATA_PEDIDA = $json.data_agendada || null;
const DURACAO   = cfg.duracao_servico;

// --- HELPER: Profissional responsável pelo dia da semana ---
function resolverProfissional(data) {
  const dt = DateTime.fromISO(data, { zone: cfg.timezone });
  const diaCfg = cfg.janelas_por_dia[dt.weekday];
  if (!diaCfg) return null;
  return { ...cfg.profissionais[diaCfg.profissional], janelas: diaCfg.janelas };
}

// Aborta imediatamente se dia da semana inválido
if ($json.dia_semana_valido === false) {
  return { json: {
    sem_disponibilidade: true,
    motivo:              'dia_semana_invalido',
    dia_semana_nome:     $json.dia_semana_nome,
    data_solicitada:     DATA_PEDIDA,
    dias_funcionamento:  'Segunda a Sábado',
    agenda_disponivel:   [],
    nome_paciente:       $json.nome_paciente,
    telefone_limpo:      $json.telefone_limpo,
    data_nascimento:     $json.data_nascimento,
    config_agenda:       cfg
  }};
}

// --- HEADERS ---
const headersJSON = {
  'Content-Type':  'application/json',
  'Accept':        'application/json',
  'Authorization': 'Bearer ' + cfg.authorization
};
const headersForm = {
  'Content-Type':  'application/x-www-form-urlencoded',
  'Accept':        'application/json',
  'Authorization': 'Bearer ' + cfg.authorization
};

// --- HELPER: GET com fallback POST ---
async function buscarComFallback(endpoint, params) {
  const tentativas = [
    () => this.helpers.httpRequest({ method: 'GET',  url: endpoint, headers: headersJSON, qs:   params, json: true }),
    () => this.helpers.httpRequest({ method: 'POST', url: endpoint, headers: headersForm, form: params, json: true }),
    () => this.helpers.httpRequest({ method: 'POST', url: endpoint, headers: headersJSON, body: params, json: true }),
  ];
  let lastError;
  for (const fn of tentativas) {
    try { return await fn(); }
    catch (err) { lastError = err; if (!err.message.includes('405')) throw err; }
  }
  throw lastError;
}

// --- HELPER: Converte HH:MM para minutos ---
const toMin = h => { const [hh, mm] = h.split(':').map(Number); return hh * 60 + mm; };

// --- HELPER: Converte minutos para HH:MM ---
const toHHMM = m => String(Math.floor(m / 60)).padStart(2,'0') + ':' + String(m % 60).padStart(2,'0');

// --- HELPER: Filtra horários válidos considerando duração e janelas ---
function filtrarSlotsValidos(horariosLivres, janelas, duracao) {
  const livresSet = new Set(horariosLivres);
  return horariosLivres.filter(slot => {
    const slotMin = toMin(slot);
    const fimSlot = slotMin + duracao;
    const cabeNaJanela = janelas.some(j => {
      const fimJanela = toMin(j.fim);
      return slotMin >= toMin(j.inicio) && fimSlot <= fimJanela;
    });
    if (!cabeNaJanela) return false;
    for (let m = slotMin + 5; m < fimSlot; m += 5) {
      if (!livresSet.has(toHHMM(m))) return false;
    }
    return true;
  });
}

// --- HELPER: Normaliza e busca slots de uma data ---
async function buscarSlots(data) {
  const prof = resolverProfissional(data);
  if (!prof) return { data, horarios: [], erro: null };
  try {
    const res      = await buscarComFallback.call(this, `${BASE_URL}/horariolivre/${prof.idpro}`, { data });
    const listaRaw = Array.isArray(res) ? res : (res.horarios ?? res.horas ?? res.times ?? res.slots ?? []);
    const horarios = listaRaw
      .map(h => typeof h === 'string' ? h : (h.hora ?? h.time ?? h.horario ?? ''))
      .filter(Boolean);
    return { data, horarios: filtrarSlotsValidos(horarios, prof.janelas, DURACAO), profissional: prof.nome, idpro: prof.idpro, erro: null };
  } catch (err) {
    return { data, horarios: [], profissional: prof.nome, idpro: prof.idpro, erro: err.message };
  }
}

// --- BUSCAR DATAS DISPONÍVEIS (une as agendas de todos os profissionais) ---
const idprosUnicos = [...new Set(Object.values(cfg.profissionais).map(p => p.idpro))];
let todasDatas = [];
try {
  const listas = await Promise.all(idprosUnicos.map(async idpro => {
    const res   = await buscarComFallback.call(this, `${BASE_URL}/datalivre/${idpro}`, { data: $json.data_inicio });
    const lista = Array.isArray(res) ? res : (res.datas ?? res.data ?? res.dates ?? []);
    return lista.map(item => typeof item === 'string' ? item : (item.data ?? item.date ?? item.dia ?? '')).filter(Boolean);
  }));
  todasDatas = [...new Set(listas.flat())].sort();
} catch (err) {
  return { json: {
    sem_disponibilidade: true,
    erro:                `Falha ao buscar datas: ${err.message}`,
    agenda_disponivel:   [],
    nome_paciente:       $json.nome_paciente,
    telefone_limpo:      $json.telefone_limpo,
    config_agenda:       cfg
  }};
}

if (todasDatas.length === 0) {
  return { json: {
    sem_disponibilidade: true,
    agenda_disponivel:   [],
    mensagem:            'Nenhuma data disponível no período.',
    nome_paciente:       $json.nome_paciente,
    telefone_limpo:      $json.telefone_limpo,
    config_agenda:       cfg
  }};
}

// --- DEFINIR DATAS ALVO ---
let datasAlvo    = [];
let modoConsulta = '';

if (DATA_PEDIDA) {
  if (todasDatas.includes(DATA_PEDIDA)) {
    datasAlvo    = [DATA_PEDIDA];
    modoConsulta = 'data_especifica';
  } else {
    datasAlvo    = todasDatas.slice(0, 15);
    modoConsulta = 'fallback_data_indisponivel';
  }
} else {
  datasAlvo    = todasDatas.slice(0, 15);
  modoConsulta = 'exploracao_livre';
}

// --- BUSCAR SLOTS ---
let resultados = await Promise.all(datasAlvo.map(data => buscarSlots.call(this, data)));

if (modoConsulta === 'data_especifica' && resultados[0].horarios.length === 0) {
  const alternativas = todasDatas.filter(d => d !== DATA_PEDIDA).slice(0, 15);
  if (alternativas.length > 0) {
    resultados   = await Promise.all(alternativas.map(data => buscarSlots.call(this, data)));
    modoConsulta = 'fallback_dia_cheio';
  }
}

const agendaDisponivel = resultados
  .filter(r => r.horarios.length > 0)
  .map(r => ({ data: r.data, horarios: r.horarios, profissional: r.profissional, idpro: r.idpro }));

return { json: {
  agenda_disponivel:   agendaDisponivel,
  sem_disponibilidade: agendaDisponivel.length === 0,
  total_datas:         agendaDisponivel.length,
  total_slots:         agendaDisponivel.reduce((acc, d) => acc + d.horarios.length, 0),
  modo_consulta:       modoConsulta,
  data_solicitada:     DATA_PEDIDA,
  datas_consultadas:   resultados.map(r => r.data),
  todas_datas_api:     todasDatas,
  erros_parciais:      resultados.filter(r => r.erro).map(r => ({ data: r.data, erro: r.erro })),
  nome_paciente:       $json.nome_paciente,
  telefone_limpo:      $json.telefone_limpo,
  data_nascimento:     $json.data_nascimento,
  config_agenda:       cfg
}};

// ============================================================
// FORMATAR SUGESTÕES
// Gera texto amigável com opções de manhã e tarde
// ============================================================
const cfg            = $json.config_agenda;
const DURACAO        = cfg.duracao_servico;
const agendaDisponivel = $json.agenda_disponivel || [];

const toMin = h => { const [hh, mm] = h.split(':').map(Number); return hh * 60 + mm; };

function gerarGrade(inicio, fim, duracao) {
  const inicioMin = toMin(inicio);
  const fimMin    = toMin(fim);
  const slots     = [];
  let cursor      = inicioMin;
  while (cursor + duracao <= fimMin) {
    const h = String(Math.floor(cursor / 60)).padStart(2, '0');
    const m = String(cursor % 60).padStart(2, '0');
    slots.push(`${h}:${m}`);
    cursor += duracao;
  }
  return slots;
}

function fmtData(d) {
  const [ano, mes, dia] = d.split('-');
  return `${dia}/${mes}/${ano}`;
}

function diaSem(d) {
  const dt   = new Date(`${d}T12:00:00`);
  const DIAS = ['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
  return DIAS[dt.getDay()];
}

function janelasDoDia(d) {
  const jsDay   = new Date(`${d}T12:00:00`).getDay();
  const weekday = jsDay === 0 ? 7 : jsDay;
  const diaCfg  = cfg.janelas_por_dia[weekday];
  return diaCfg ? diaCfg.janelas : [];
}

const sugestoes = agendaDisponivel.map(dia => {
  const livres = new Set(dia.horarios);
  const grades = janelasDoDia(dia.data).map(j => ({
    periodo: toMin(j.inicio) < 12 * 60 ? 'manha' : 'tarde',
    slots:   gerarGrade(j.inicio, j.fim, DURACAO)
  }));
  let slotManha = null;
  let slotTarde = null;
  for (const grade of grades) {
    const primeiroLivre = grade.slots.find(s => livres.has(s)) ?? null;
    if (grade.periodo === 'manha') slotManha = primeiroLivre;
    if (grade.periodo === 'tarde') slotTarde = primeiroLivre;
  }
  return {
    data:         dia.data,
    profissional: dia.profissional || null,
    slot_manha:   slotManha,
    slot_tarde:   slotTarde,
    tem_manha:    slotManha !== null,
    tem_tarde:    slotTarde !== null,
    tem_opcao:    slotManha !== null || slotTarde !== null
  };
}).filter(s => s.tem_opcao);

const opcoes = sugestoes.map(s => {
  const sufixoProf = s.profissional ? ` (Dr(a). ${s.profissional})` : '';
  const linhas = [`📅 *${diaSem(s.data)}*, ${fmtData(s.data)}${sufixoProf}`];
  if (s.slot_manha) linhas.push(`   ☀️ Manhã: *${s.slot_manha}*`);
  if (s.slot_tarde) linhas.push(`   🌆 Tarde: *${s.slot_tarde}*`);
  return linhas.join('\n');
});

return { json: {
  sugestoes,
  texto_sugestoes:     opcoes.join('\n\n'),
  tem_disponibilidade: sugestoes.length > 0,
  total_opcoes:        sugestoes.length,
  modo_consulta:       $json.modo_consulta,
  data_solicitada:     $json.data_solicitada || null,
  janelas_por_dia:     cfg.janelas_por_dia,
  nome_paciente:       $json.nome_paciente,
  telefone_limpo:      $json.telefone_limpo,
  data_nascimento:     $json.data_nascimento,
  config_agenda:       cfg
}};

// ============================================================
// VALIDAR SLOT - AGENDAR
// Verifica se data+horário informados são válidos e livres
// ============================================================
const cfg           = $json.config_agenda;
const BASE_URL      = 'https://eclinica.app/api/v2';
const DURACAO       = cfg.duracao_servico;
const dataPedida    = $json.data_agendada    || '';
const horarioPedido = $json.horario_agendado || '';

// --- HELPER: Normaliza horário para HH:MM ---
const norm = h => {
  if (!h) return '';
  const partes = h.toString().split(':');
  return partes[0].padStart(2, '0') + ':' + (partes[1] || '00').padStart(2, '0');
};

// --- HELPER: Gera grade de horários válidos ---
function gerarGrade(inicio, fim, duracao) {
  const [hi, mi] = inicio.split(':').map(Number);
  const [hf, mf] = fim.split(':').map(Number);
  const fimMin   = hf * 60 + mf;
  const slots    = [];
  let cursor     = hi * 60 + mi;
  while (cursor <= fimMin) {
    const h = String(Math.floor(cursor / 60)).padStart(2, '0');
    const m = String(cursor % 60).padStart(2, '0');
    slots.push(`${h}:${m}`);
    cursor += duracao;
  }
  return slots;
}

// Validações iniciais
if (!dataPedida)    return { json: { ...$json, validacao: { aprovado: false, motivo: 'Data não informada.' } } };
if (!horarioPedido) return { json: { ...$json, validacao: { aprovado: false, motivo: 'Horário não informado.' } } };

const dtPedida       = DateTime.fromISO(dataPedida, { zone: cfg.timezone });
const diaCfg         = cfg.janelas_por_dia[dtPedida.weekday] || null;
const prof           = diaCfg ? cfg.profissionais[diaCfg.profissional] : null;
const janelasDoDia   = diaCfg ? diaCfg.janelas : [];
const gradeCompleta  = janelasDoDia.flatMap(j => gerarGrade(j.inicio, j.fim, DURACAO));
const horarioNorm    = norm(horarioPedido);

if (!prof || !gradeCompleta.includes(horarioNorm)) {
  return { json: {
    ...$json,
    validacao:    { aprovado: false, motivo: prof ? `O horário ${horarioNorm} não faz parte da grade. Válidos: ${gradeCompleta.join(', ')}.` : 'Não há atendimento nesse dia da semana.' },
    hora_validada: horarioNorm,
    grade_clinica: gradeCompleta
  }};
}

// Consulta horários livres na API
const headersJSON = { 'Content-Type': 'application/json', 'Accept': 'application/json', 'Authorization': 'Bearer ' + cfg.authorization };
const headersForm = { 'Content-Type': 'application/x-www-form-urlencoded', 'Accept': 'application/json', 'Authorization': 'Bearer ' + cfg.authorization };

async function buscarComFallback(endpoint, params) {
  const tentativas = [
    () => this.helpers.httpRequest({ method: 'GET',  url: endpoint, headers: headersJSON, qs:   params, json: true }),
    () => this.helpers.httpRequest({ method: 'POST', url: endpoint, headers: headersForm, form: params, json: true }),
    () => this.helpers.httpRequest({ method: 'POST', url: endpoint, headers: headersJSON, body: params, json: true }),
  ];
  let lastError;
  for (const fn of tentativas) {
    try { return await fn(); }
    catch (err) { lastError = err; if (!err.message.includes('405')) throw err; }
  }
  throw lastError;
}

let horariosLivres = [];
try {
  const res      = await buscarComFallback.call(this, `${BASE_URL}/horariolivre/${prof.idpro}`, { data: dataPedida });
  const listaRaw = Array.isArray(res) ? res : (res.horarios ?? res.horas ?? res.times ?? res.slots ?? []);
  horariosLivres = listaRaw
    .map(h => norm(typeof h === 'string' ? h : (h.hora ?? h.time ?? h.horario ?? '')))
    .filter(Boolean);
} catch (err) {
  return { json: {
    ...$json,
    validacao:    { aprovado: false, motivo: `Falha ao consultar agenda: ${err.message}` },
    hora_validada: horarioNorm,
    grade_clinica: gradeCompleta
  }};
}

const disponivel = new Set(horariosLivres).has(horarioNorm);

return { json: {
  ...$json,
  validacao:        disponivel
                    ? { aprovado: true,  motivo: 'Horário disponível.' }
                    : { aprovado: false, motivo: `O horário ${horarioNorm} já está ocupado em ${dataPedida}.` },
  hora_validada:       horarioNorm,
  grade_clinica:       gradeCompleta,
  total_livres_api:    horariosLivres.length,
  profissional_resolvido: prof
}};

// ============================================================
// RESOLVER PROFISSIONAL - CANCELAR
// Descobre o idpro do dia da agenda a cancelar
// ============================================================
const cfg  = $('Configuracao Unidades').first().json;
const dt   = DateTime.fromISO(cfg.data_agendada, { zone: cfg.config_agenda.timezone });
const diaCfg = cfg.config_agenda.janelas_por_dia[dt.weekday];
const idproResolvido = diaCfg ? cfg.config_agenda.profissionais[diaCfg.profissional].idpro : '';

return { json: { ...$json, idpro_resolvido: idproResolvido } };

// ============================================================
// FILTRAR AGENDAMENTO PARA CANCELAR
// Localiza agendamento do paciente e verifica situação atual
// CORREÇÃO: lógica de ja_cancelado separada corretamente
// ============================================================
const cfg         = $('Configuracao Unidades').first().json;
const horaAlvo    = cfg.horario_agendado;
const foneEnviado = cfg.telefone_limpo.toString().replace(/\D/g, '');

const norm     = h => { if (!h) return ''; const p = h.toString().split(':'); return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'0'); };
const normFone = f => (f || '').toString().replace(/\D/g, '');

// --- LOCALIZAR CLIENTE ---
const clientes       = $('Buscar Paciente Cancelar').all().map(i => i.json);
const clienteAchado  = clientes.find(c => {
  const cel = normFone(c.celular);
  const tel = normFone(c.telefone);
  return foneEnviado.endsWith(cel) || cel.endsWith(foneEnviado) ||
         foneEnviado.endsWith(tel) || tel.endsWith(foneEnviado);
});
const idCliente = clienteAchado?.id ?? null;

// --- LOCALIZAR AGENDAMENTO ---
const agendamentos = $input.all().map(i => i.json);
let encontrado     = null;

if (idCliente) {
  // Tenta achar pelo horário exato primeiro
  if (horaAlvo) {
    encontrado = agendamentos.find(a =>
      String(a.idcliente) === String(idCliente) && norm(a.hora) === norm(horaAlvo)
    );
  }
  // Fallback: qualquer agendamento do paciente naquele dia
  if (!encontrado) {
    encontrado = agendamentos.find(a => String(a.idcliente) === String(idCliente));
  }
}

// --- DETERMINAR SITUAÇÃO ---
// Separar claramente os três estados possíveis
const situacao   = (encontrado?.situacao || '').toString().toUpperCase().trim();
const jaCancelado        = encontrado !== null && situacao === 'DESMARCADO';
const agendamentoAtivo   = encontrado !== null && !jaCancelado && idCliente !== null;

return { json: {
  ...cfg,
  agendamento_id:          encontrado?.idagenda ?? null,
  agendamento_encontrado:  agendamentoAtivo,
  ja_cancelado:            jaCancelado,
  situacao_api:            encontrado?.situacao ?? null,
  id_cliente:              idCliente,
  hora_cancelada:          encontrado ? norm(encontrado.hora) : null,
  dados_agendamento:       encontrado || null
}};

// ============================================================
// RESOLVER PROFISSIONAL - REMARCAR (agendamento antigo)
// Descobre o idpro do dia da agenda antiga
// ============================================================
const cfg  = $('Configuracao Unidades').first().json;
const dt   = DateTime.fromISO(cfg.data_antiga, { zone: cfg.config_agenda.timezone });
