  data_hora_antiga:         encontrado ? `${cfg.data_antiga} ${norm(encontrado.hora)}` : null,
  dados_agendamento_antigo: encontrado || null
}};

// ============================================================
// RESOLVER PROFISSIONAL - VERIFICAR SLOTS REMARCAR (data nova)
// Descobre o idpro do dia da nova data pedida
// ============================================================
const dt   = DateTime.fromISO($json.data_agendada, { zone: $json.config_agenda.timezone });
const diaCfg = $json.config_agenda.janelas_por_dia[dt.weekday];
const idproResolvido = diaCfg ? $json.config_agenda.profissionais[diaCfg.profissional].idpro : '';

return { json: { ...$json, idpro_resolvido: idproResolvido } };

// ============================================================
// VALIDAR SLOT NOVO - REMARCAR
// Confirma que o novo horário pedido está disponível
// ============================================================
const cfg    = $('Configuracao Unidades').first().json;
const DURACAO = cfg.config_agenda.duracao_servico;

const norm = h => { if (!h) return ''; const p = h.toString().split(':'); return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'0'); };

function gerarGrade(inicio, fim, duracao) {
  const [hi, mi] = inicio.split(':').map(Number);
  const [hf, mf] = fim.split(':').map(Number);
  const fimMin   = hf * 60 + mf;
  const slots    = [];
  let cursor     = hi * 60 + mi;
  while (cursor <= fimMin) {
    const h = String(Math.floor(cursor / 60)).padStart(2, '0');
    const m = String(cursor % 60).padStart(2, '0');
    slots.push(`${h}:${m}`);
    cursor += duracao;
  }
  return slots;
}

const dtNovo         = DateTime.fromISO(cfg.data_agendada, { zone: cfg.config_agenda.timezone });
const diaCfg         = cfg.config_agenda.janelas_por_dia[dtNovo.weekday] || null;
const prof           = diaCfg ? cfg.config_agenda.profissionais[diaCfg.profissional] : null;
const janelasDoDia   = diaCfg ? diaCfg.janelas : [];
const gradeCompleta  = janelasDoDia.flatMap(j => gerarGrade(j.inicio, j.fim, DURACAO));
const hAlvo          = norm(cfg.horario_agendado || '');

const listaRaw       = $input.all().map(i => i.json);
const horariosLivres = new Set(
  listaRaw.map(h => norm(typeof h === 'string' ? h : (h.hora ?? h.time ?? h.horario ?? ''))).filter(Boolean)
);

let validacao;
if      (!hAlvo)                          validacao = { aprovado: false, motivo: 'Horário não informado.' };
else if (!prof)                           validacao = { aprovado: false, motivo: 'Não há atendimento nesse dia da semana.' };
else if (!gradeCompleta.includes(hAlvo))  validacao = { aprovado: false, motivo: `O horário ${hAlvo} não faz parte da grade. Válidos: ${gradeCompleta.join(', ')}.` };
else if (horariosLivres.has(hAlvo))       validacao = { aprovado: true,  motivo: 'Horário disponível.' };
else                                      validacao = { aprovado: false, motivo: `O horário ${hAlvo} em ${cfg.data_agendada} já está ocupado.` };

const filtrado = $('Filtrar Agmt Antigo').first().json;

return { json: {
  ...cfg,
  validacao,
  hora_nova_validada:     hAlvo,
  grade_clinica:          gradeCompleta,
  agendamento_id_antigo:  filtrado.agendamento_id_antigo,
  id_cliente:             filtrado.id_cliente,
  profissional_resolvido: prof
}};

// ============================================================
// FILTRAR AGENDAMENTO - CONSULTAR
// Retorna status atual do agendamento do paciente
// ============================================================
const cfg         = $('Configuracao Unidades').first().json;
const foneEnviado = cfg.telefone_limpo.toString().replace(/\D/g, '');

const norm     = h => { if (!h) return ''; const p = h.toString().split(':'); return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'0'); };
const normFone = f => (f || '').toString().replace(/\D/g, '');

// --- LOCALIZAR CLIENTE ---
const clientes      = $('Buscar Paciente Consultar').all().map(i => i.json);
const clienteAchado = clientes.find(c => {
  const cel = normFone(c.celular);
  const tel = normFone(c.telefone);
  return foneEnviado.endsWith(cel) || cel.endsWith(foneEnviado) ||
         foneEnviado.endsWith(tel) || tel.endsWith(foneEnviado);
});
const idCliente = clienteAchado?.id ?? null;

if (!idCliente) {
  return { json: {
    ...cfg,
    consulta_status:        'paciente_nao_encontrado',
    agendamento_ativo:      false,
    agendamento_encontrado: false,
    mensagem:               'Paciente não encontrado na base da clínica.',
    dados_agendamento:      null
  }};
}

// --- LOCALIZAR AGENDAMENTO ---
const agendamentos   = $input.all().map(i => i.json);
const agmtsPaciente  = agendamentos.filter(a => String(a.idcliente) === String(idCliente));

const horaAlvo = norm(cfg.horario_agendado || '');
let encontrado = horaAlvo
  ? (agmtsPaciente.find(a => norm(a.hora) === horaAlvo) ?? agmtsPaciente[0] ?? null)
  : (agmtsPaciente[0] ?? null);

// --- DETERMINAR STATUS ---
const SITUACOES_ATIVAS = ['MARCADO', 'CONFIRMADO', 'AGENDADO', 'ATIVO', ''];
let consulta_status, mensagem;

if (!encontrado) {
  consulta_status = 'nao_encontrado';
  mensagem        = `ℹ️ Não há agendamento para este paciente em ${cfg.data_agendada}.`;
} else {
  const situacaoRaw = (encontrado.situacao || '').toString().toUpperCase().trim();
  const estaAtivo   = SITUACOES_ATIVAS.includes(situacaoRaw);
  if (estaAtivo) {
    consulta_status = 'confirmado';
    mensagem        = `✅ Agendamento confirmado para ${cfg.data_agendada} às ${norm(encontrado.hora)}.`;
  } else {
    consulta_status = 'desmarcado';
    mensagem        = `❌ O agendamento de ${cfg.data_agendada} às ${norm(encontrado.hora)} está ${situacaoRaw}.`;
  }
}

return { json: {
  ...cfg,
  consulta_status,
  agendamento_ativo:      consulta_status === 'confirmado',
  agendamento_encontrado: !!encontrado,
  situacao_api:           encontrado?.situacao ?? null,
  id_cliente:             idCliente,
  dados_agendamento:      encontrado || null,
  hora_agendada:          encontrado ? norm(encontrado.hora) : null,
  data_hora_agendada:     encontrado ? `${cfg.data_agendada} ${norm(encontrado.hora)}` : null,
  mensagem
}};

